import {poweredDevice,pinVoltage,logic} from './bus-electrical.js';
import {MFRC522} from './expansion-nfc.js';
import {XPT2046,EPaper,MCP2515} from './expansion-display-controllers.js';
import {SPIFlash,SDCard} from './expansion-spi.js';
export const EXPANSION_RUNTIME_TYPES=['a4988','drv8825','buzzerActive','buzzerPassive','dcmotor','spiFlash','sdCard','xpt2046','epaper','mcp2515','i2sMic','i2sAmp','irReceiver','irEmitter','rs485','mfrc522'];
export function attachExpansionRuntime(runtime,engine,initial){let project=initial,states=new Map(),busy=false,disposed=false,key='';
 const refresh=()=>{if(busy||disposed)return;busy=true;try{const dc=engine.solution,drivers=[],now=runtime.cpu.cycles;for(const d of states.values()){const c=project.components.find(c=>c.id===d.id);if(!c)continue;const v=pin=>pinVoltage(dc,d.id,pin);if(d.type==='dcmotor'){const volts=v('P')-v('N');d.voltage=Number.isFinite(volts)?volts:0;d.rpm=d.voltage/(c.params.nominalVoltage??5)*(c.params.nominalRPM??200);continue;}if(d.type==='irEmitter'){const high=(dc.ledResults.get(d.id+':ir')?.current||0)>.0001;if(high&&!d.high){if(d.rise!==null&&now>d.rise)d.frequency=16000000/(now-d.rise);d.rise=now;if(d.frequency>=30000&&d.frequency<=60000){d.carrierUntil=now+2400;const token=++d.opticalEpoch;runtime.cpu.addClockEvent(()=>{if(disposed||d.opticalEpoch!==token)return;refresh();},2400);}}d.high=high;d.on=(d.carrierUntil??0)>now;continue;}if(d.type==='buzzerPassive'){const volts=v('P')-v('N'),high=Number.isFinite(volts)&&volts>=1;if(high&&!d.high){if(d.rise!==null&&now>d.rise)d.frequency=16000000/(now-d.rise);d.rise=now;d.edges++;}d.high=high;d.on=d.edges>1&&now-(d.rise??0)<1600000;continue;}const power=poweredDevice(dc,d.id,{min:['a4988','drv8825'].includes(d.type)?2.7:2.5,max:['spiFlash','sdCard'].includes(d.type)?3.6:5.5}),level=pin=>logic(v(pin),power.voltage);if(d.powered&&!power.powered){d.controller?.reset();d.enabled=false;d.high=null;d.lastClock=null;}Object.assign(d,power);if(!d.powered)continue;
 if(d.type==='irReceiver'){d.on=[...states.values()].some(e=>e.type==='irEmitter'&&(e.carrierUntil??0)>now&&((project.components.find(c=>c.id===e.id)?.params.channel)??1)===(c.params.channel??1));drivers.push({endpoint:d.id+':OUT',voltage:d.on?0:power.voltage,ohms:50});continue;}
 if(d.type==='rs485'){const enabled=level('DE')===true;if(enabled){const high=level('DI');if(high!==null)drivers.push({endpoint:d.id+':A',voltage:high?power.voltage:0,ohms:50},{endpoint:d.id+':B',voltage:high?0:power.voltage,ohms:50});}if(level('RE')===false&&Number.isFinite(v('A'))&&Number.isFinite(v('B'))&&Math.abs(v('A')-v('B'))>=.2)drivers.push({endpoint:d.id+':RO',voltage:v('A')>v('B')?power.voltage:0,ohms:50});d.enabled=enabled;continue;}
 if(['i2sMic','i2sAmp'].includes(d.type)){const clk=level('BCLK'),ws=level('WS');if(ws!==d.ws){d.audioBit=0;d.audioWord=0;d.ws=ws;d.audioOut=false;}if(clk===true&&d.lastClock===false){const bit=d.audioBit??0;if(d.type==='i2sAmp'&&bit>=1&&bit<=24){const value=level('DIN');if(value!==null)d.audioWord=((d.audioWord||0)<<1)|(value?1:0);}d.audioBit=(bit+1)%32;if(bit===24&&d.type==='i2sAmp'){const w=d.audioWord&0xffffff;d.pcm=w&0x800000?w-16777216:w;d.samples=(d.samples||0)+1;}}if(d.type==='i2sMic'){const bit=d.audioBit??0,active=ws===(level('LR')===true),sample=(c.params.sample??1048576)&0xffffff;if(clk===false&&d.lastClock===true)d.audioOut=!!(active&&bit>=1&&bit<=24&&(sample&(1<<(24-bit))));drivers.push({endpoint:d.id+':DOUT',voltage:d.audioOut?power.voltage:0,ohms:50});}else if(level('SD')!==false){const value=(d.pcm||0)/8388608;drivers.push({endpoint:d.id+':SPK+',voltage:power.voltage*(.5+.5*value),ohms:2},{endpoint:d.id+':SPK-',voltage:power.voltage*(.5-.5*value),ohms:2});}d.lastClock=clk;continue;}
 if(d.type==='buzzerActive'){d.on=level('IN')===true;d.frequency=d.on?c.params.frequency??2300:0;continue;}
 if(['a4988','drv8825'].includes(d.type)){const step=level('STEP'),dir=level('DIR'),reset=level('RESET'),sleep=level('SLEEP'),vm=v('VMOT');if(reset===false){d.steps=0;d.phase=0;}d.enabled=level('ENABLE')===false&&reset===true&&sleep===true&&vm>=8&&vm<=45;const micro=['MS1','MS2','MS3'].reduce((n,p,i)=>n|(level(p)===true?1<<i:0),0),div=d.type==='a4988'?[1,2,4,8,16,16,16,16][micro]:[1,2,4,8,16,32,32,32][micro];if(d.enabled&&step===true&&d.high===false&&dir!==null){d.steps+=(dir?1:-1)/div;d.phase+=dir?1:-1;d.pulses++;}d.high=step;d.divider=div;const phase=d.steps/4*Math.PI*2,currents=[Math.sin(phase),Math.cos(phase)];for(let i=0;i<2;i++){const a=i?'B':'A',on=currents[i]>=0;for(const[pin,high]of [[a+'1',on],[a+'2',!on]])if(d.enabled)drivers.push({endpoint:d.id+':'+pin,voltage:high?vm:0,ohms:2});}d.angle=d.steps*1.8;continue;}
 if(d.controller){d.controller.setEnvironment?.(c.params);d.controller.setPins?.({dc:level('DC'),reset:level('RST')});d.controller.tick?.(now);for(const x of d.controller.drivers?.(power.voltage)||[])drivers.push({...x,endpoint:d.id+':'+x.pin});const event=d.controller.nextEvent?.(now);if(Number.isFinite(event)&&event!==d.eventAt){d.eventAt=event;runtime.cpu.addClockEvent(()=>{if(disposed)return;d.eventAt=null;refresh();},Math.max(1,event-now));}const clk=level('SCK'),cs=level('CS'),mosi=level('MOSI');d.connected=[clk,cs,mosi].every(v=>v!==null)&&['SCK','CS','MOSI'].every(p=>v(p)>=-.3&&v(p)<=power.voltage+.3);if(d.connected){if(cs!==d.lastCS){if(cs)d.controller.deselect(now);else d.controller.select(now);d.bits=0;d.shift=0;d.tx=d.controller.tx??255;d.outBit=!!(d.tx&128);}if(!cs&&clk===true&&d.lastClock===false){d.shift=(d.shift<<1)|(mosi?1:0);if(++d.bits===8){d.controller.transfer(d.shift&255,now);d.nextTX=d.controller.tx;d.shift=0;d.bits=0;d.bytes++;}}if(!cs&&clk===false&&d.lastClock===true){if(d.bits===0)d.tx=d.nextTX??255;d.outBit=!!(d.tx&(128>>d.bits));}if(!cs)drivers.push({endpoint:d.id+':MISO',voltage:d.outBit?power.voltage:0,ohms:50});}d.lastClock=clk;d.lastCS=cs;}
 }const next=JSON.stringify(drivers);if(next!==key){key=next;engine.setDrivers('expansion',drivers);}}finally{busy=false;}};
 const controller=c=>{if(c.type==='mfrc522')return new MFRC522();if(c.type==='xpt2046')return new XPT2046();if(c.type==='epaper')return new EPaper();if(c.type==='mcp2515')return new MCP2515();if(!['spiFlash','sdCard'].includes(c.type))return null;runtime.nonvolatile??=new Map();const key=c.id+':'+c.type;if(!runtime.nonvolatile.has(key))runtime.nonvolatile.set(key,c.type==='spiFlash'?new SPIFlash():new SDCard());return runtime.nonvolatile.get(key);};
 const update=()=>{const ids=new Set();for(const c of project.components.filter(c=>EXPANSION_RUNTIME_TYPES.includes(c.type))){ids.add(c.id);if(states.get(c.id)?.type!==c.type)states.set(c.id,{id:c.id,type:c.type,powered:false,steps:0,pulses:0,phase:0,bytes:0,opticalEpoch:0,edges:0,rise:null,high:null,controller:controller(c)});}for(const id of states.keys())if(!ids.has(id))states.delete(id);refresh();};
 update();const unsubscribe=engine.subscribe(refresh);return{updateProject(next){project=next;update();},snapshot(){refresh();return{modules:Object.fromEntries([...states].map(([id,d])=>[id,{type:d.type,powered:d.powered,connected:d.connected,enabled:d.enabled,steps:d.steps,pulses:d.pulses,angle:d.angle,divider:d.divider,rpm:d.rpm,voltage:d.voltage,on:d.on,frequency:d.frequency,pcm:d.pcm,samples:d.samples,bytes:d.bytes,...d.controller?.state()}]))};},dispose(){disposed=true;unsubscribe();engine.setDrivers('expansion',[]);}};
}
